output_text:
[
  {
    "id": "take_cart_at_entrance",
    "text": "Customers are obliged to take the entrance cart from the cart station before doing their shopping.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "items_must_go_in_cart",
    "text": "Customers are prohibited from picking up shelf items unless they currently have the cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_use": "hasCart"
      },
      "events": {
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "item_pickup",
          {
            "not": "cart_in_use"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Customers are prohibited from carrying groceries by hand rather than placing them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_cart_to_service_bay",
    "text": "After taking a cart, customers are obliged to return it by leaving it at the service bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "service_bay": "at(0,1)",
        "cart_parked_at_service_bay": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_service_bay": {
          "pre": {
            "and": [
              "service_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_service_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_service_bay"
    }
  },
  {
    "id": "exit_only_after_cart_return",
    "text": "Customers are prohibited from exiting the store before the cart is parked at the service bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_service_bay": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_parked_at_service_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_upper_right_corridor",
    "text": "Customers are prohibited from pushing carts through the upper-right pedestrian corridor.",
    "abstraction": {
      "state_properties": {
        "upper_right_pedestrian_corridor": {
          "or": [
            "at(6,2)",
            "at(7,2)",
            "at(8,2)",
            "at(6,3)",
            "at(7,3)",
            "at(8,3)"
          ]
        },
        "cart_in_use": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_in_use",
          "upper_right_pedestrian_corridor"
        ]
      }
    }
  },
  {
    "id": "do_not_abandon_cart_elsewhere",
    "text": "Customers are prohibited from leaving a cart anywhere except the designated service bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "service_bay": "at(0,1)"
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart",
          {
            "not": "service_bay"
          }
        ]
      }
    }
  },
  {
    "id": "pickup_only_at_shelf_access_points",
    "text": "Customers are prohibited from performing item-pickup interactions except at recognized shelf access points.",
    "abstraction": {
      "state_properties": {
        "apple_access_point": {
          "or": [
            "at(1,3)",
            "at(2,4)"
          ]
        },
        "bread_access_point": "at(3,4)",
        "milk_access_point": {
          "or": [
            "at(5,2)",
            "at(5,4)"
          ]
        },
        "eggs_access_point": "at(6,4)",
        "approved_item_access_point": {
          "or": [
            "apple_access_point",
            "bread_access_point",
            "milk_access_point",
            "eggs_access_point"
          ]
        }
      },
      "events": {
        "shelf_item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelf_item_pickup",
          {
            "not": "approved_item_access_point"
          }
        ]
      }
    }
  }
]
